1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"math"
7		"strings"
8		"testing"
9	)
10	
11	func runSliding(t *testing.T, input string, window, slide int64) (string, string, error) {
12		t.Helper()
13		var stdout, stderr bytes.Buffer
14		err := RunAggregateSliding(strings.NewReader(input), window, slide, &stdout, &stderr)
15		return stdout.String(), stderr.String(), err
16	}
17	
18	// The worked example from the spec: length 1000, interval 600; events at 700
19	// (value 2) and 1000 (value 3). Watermark 1000 emits only [0,1000) with one
20	// event and sum 2; watermark 1600 emits [600,1600) with both events and sum
21	// 5; the time-1000 event is outside the first window.
22	func TestAggregateSlidingSpecExample(t *testing.T) {
23		input := strings.Join([]string{
24			`{"type":"event","key":"k","time":700,"value":2}`,
25			`{"type":"event","key":"k","time":1000,"value":3}`,
26			`{"type":"watermark","time":1000}`,
27			`{"type":"watermark","time":1600}`,
28		}, "\n")
29		stdout, stderr, err := runSliding(t, input, 1000, 600)
30		if err != nil {
31			t.Fatalf("unexpected error: %v", err)
32		}
33		if stderr != "" {
34			t.Fatalf("unexpected stderr: %q", stderr)
35		}
36		want := strings.Join([]string{
37			`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
38			`{"key":"k","start":600,"end":1600,"count":2,"sum":5}`,
39			``,
40		}, "\n")
41		if stdout != want {
42			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
43		}
44	}
45	
46	// Every window-start boundary in the grid shifts membership: with
47	// window=1000, slide=600 the windows containing t=1200 are [600,1600) and
48	// [1200,2200), while t=1600 belongs to neither of those.
49	func TestAggregateSlidingMembershipBoundaries(t *testing.T) {
50		input := strings.Join([]string{
51			`{"type":"event","key":"a","time":599,"value":1}`,
52			`{"type":"event","key":"a","time":600,"value":1}`,
53			`{"type":"event","key":"a","time":999,"value":1}`,
54			`{"type":"event","key":"a","time":1000,"value":1}`,
55			`{"type":"event","key":"a","time":1199,"value":1}`,
56			`{"type":"event","key":"a","time":1200,"value":1}`,
57			`{"type":"watermark","time":2200}`,
58		}, "\n")
59		stdout, _, err := runSliding(t, input, 1000, 600)
60		if err != nil {
61			t.Fatalf("unexpected error: %v", err)
62		}
63		want := strings.Join([]string{
64			`{"key":"a","start":0,"end":1000,"count":3,"sum":3}`,    // 599,600,999
65			`{"key":"a","start":600,"end":1600,"count":5,"sum":5}`,  // 600,999,1000,1199,1200
66			`{"key":"a","start":1200,"end":2200,"count":1,"sum":1}`, // 1200
67			``,
68		}, "\n")
69		if stdout != want {
70			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
71		}
72	}
73	
74	// A non-dividing interval keeps the "event at end is outside" boundary for
75	// every window; length 1000, slide 300 gives at most 4 covering windows and
76	// windows with no events are not emitted.
77	func TestAggregateSlidingNonDividingInterval(t *testing.T) {
78		input := strings.Join([]string{
79			`{"type":"event","key":"k","time":0,"value":1}`,
80			`{"type":"event","key":"k","time":700,"value":1}`,
81			`{"type":"watermark","time":2000}`,
82		}, "\n")
83		stdout, _, err := runSliding(t, input, 1000, 300)
84		if err != nil {
85			t.Fatalf("unexpected error: %v", err)
86		}
87		want := strings.Join([]string{
88			`{"key":"k","start":0,"end":1000,"count":2,"sum":2}`,   // 0 and 700
89			`{"key":"k","start":300,"end":1300,"count":1,"sum":1}`, // 700
90			`{"key":"k","start":600,"end":1600,"count":1,"sum":1}`, // 700
91			// [900,1900) has no events and is not emitted; [1200,2200) stays open.
92			``,
93		}, "\n")
94		if stdout != want {
95			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
96		}
97	}
98	
99	// When one watermark advance closes several windows, output is ordered by
100	// end ascending and then by key in UTF-8 byte order.
101	func TestAggregateSlidingClosureOrder(t *testing.T) {
102		input := strings.Join([]string{
103			`{"type":"event","key":"中","time":700,"value":1}`,
104			`{"type":"event","key":"A","time":700,"value":1}`,
105			`{"type":"event","key":"é","time":100,"value":1}`,
106			`{"type":"event","key":"A","time":1100,"value":1}`,
107			`{"type":"watermark","time":1600}`,
108		}, "\n")
109		stdout, _, err := runSliding(t, input, 1000, 600)
110		if err != nil {
111			t.Fatalf("unexpected error: %v", err)
112		}
113		lines := strings.Split(strings.TrimSuffix(stdout, "\n"), "\n")
114		type row struct {
115			key        string
116			start, end int64
117		}
118		var got []row
119		for _, line := range lines {
120			var r struct {
121				Key   string `json:"key"`
122				Start int64  `json:"start"`
123				End   int64  `json:"end"`
124			}
125			if err := json.Unmarshal([]byte(line), &r); err != nil {
126				t.Fatalf("invalid output line %q: %v", line, err)
127			}
128			got = append(got, row{r.Key, r.Start, r.End})
129		}
130		want := []row{
131			{"A", 0, 1000},
132			{"é", 0, 1000},
133			{"中", 0, 1000},
134			{"A", 600, 1600},
135			{"中", 600, 1600},
136		}
137		if len(got) != len(want) {
138			t.Fatalf("got %d rows %v, want %d rows %v", len(got), got, len(want), want)
139		}
140		for i := range want {
141			if got[i] != want[i] {
142				t.Fatalf("row %d = %v, want %v\nfull output:\n%s", i, got[i], want[i], stdout)
143			}
144		}
145	}
146	
147	// Empty windows never produce output, and still-open windows are not flushed
148	// at end of input.
149	func TestAggregateSlidingNoEmptyWindowsAndNoEOFFlush(t *testing.T) {
150		input := strings.Join([]string{
151			`{"type":"event","key":"k","time":100,"value":1}`,
152			`{"type":"watermark","time":999}`, // closes nothing
153		}, "\n")
154		stdout, _, err := runSliding(t, input, 1000, 300)
155		if err != nil {
156			t.Fatalf("unexpected error: %v", err)
157		}
158		if stdout != "" {
159			t.Fatalf("nothing should close at watermark 999, got %q", stdout)
160		}
161	}
162	
163	// Late events are skipped wholesale even when their time still falls inside
164	// an unclosed overlapping window; the note keeps the physical line number.
165	// An event exactly at the watermark remains valid.
166	func TestAggregateSlidingLateEvenInsideOverlap(t *testing.T) {
167		input := strings.Join([]string{
168			``, // line 1 blank
169			`{"type":"event","key":"k","time":900,"value":7}`,
170			`{"type":"watermark","time":1000}`,                 // closes [0,1000); [600,1600) stays open
171			`{"type":"event","key":"k","time":999,"value":1}`,  // line 4: late, even though [600,1600) is still open
172			`{"type":"event","key":"k","time":1000,"value":3}`, // line 5: boundary valid -> [600,1600)
173			`{"type":"watermark","time":1600}`,
174		}, "\n")
175		stdout, stderr, err := runSliding(t, input, 1000, 600)
176		if err != nil {
177			t.Fatalf("unexpected error: %v", err)
178		}
179		// The pre-watermark time-900 event and the boundary time-1000 event both
180		// accumulated into [600,1600); the late time-999 event must not.
181		want := strings.Join([]string{
182			`{"key":"k","start":0,"end":1000,"count":1,"sum":7}`,
183			`{"key":"k","start":600,"end":1600,"count":2,"sum":10}`,
184			``,
185		}, "\n")
186		if stdout != want {
187			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
188		}
189		wantErr := "line 4: late event time=999 below current watermark 1000, skipped\n"
190		if stderr != wantErr {
191			t.Fatalf("stderr = %q, want %q", stderr, wantErr)
192		}
193	}
194	
195	// Out-of-order arrival does not change window assignment; duplicate input
196	// lines count as separate events in every containing window.
197	func TestAggregateSlidingOutOfOrderAndDuplicates(t *testing.T) {
198		input := strings.Join([]string{
199			`{"type":"watermark","time":1000}`,
200			`{"type":"event","key":"k","time":700,"value":2}`,  // late: 700 < 1000
201			`{"type":"event","key":"k","time":1000,"value":3}`, // boundary valid
202			`{"type":"event","key":"k","time":1200,"value":4}`, // valid
203			`{"type":"event","key":"k","time":1000,"value":3}`, // duplicate of line 3
204			`{"type":"watermark","time":1600}`,
205		}, "\n")
206		stdout, stderr, err := runSliding(t, input, 1000, 600)
207		if err != nil {
208			t.Fatalf("unexpected error: %v", err)
209		}
210		// [600,1600) gets both time-1000 duplicates (3+3=6) plus time-1200 (4).
211		want := `{"key":"k","start":600,"end":1600,"count":3,"sum":10}` + "\n"
212		if stdout != want {
213			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
214		}
215		if !strings.Contains(stderr, "line 2: late event time=700") {
216			t.Fatalf("expected late note for line 2, got %q", stderr)
217		}
218	}
219	
220	// Invalid slide arguments are rejected before input is read.
221	func TestAggregateSlidingInvalidArguments(t *testing.T) {
222		cases := []struct {
223			name   string
224			w, sl  int64
225			wantIn string
226		}{
227			{"zero slide", 1000, 0, "positive"},
228			{"negative slide", 1000, -600, "positive"},
229			{"min slide", 1000, math.MinInt64, "positive"},
230			{"slide exceeds window", 1000, 1001, "must not exceed"},
231			{"zero window", 0, 0, "window length"},
232			{"negative window", -1, -1, "window length"},
233		}
234		for _, tc := range cases {
235			t.Run(tc.name, func(t *testing.T) {
236				err := RunAggregateSliding(strings.NewReader("not consumed\n"), tc.w, tc.sl, &bytes.Buffer{}, &bytes.Buffer{})
237				if err == nil {
238					t.Fatal("expected error, got nil")
239				}
240				if !strings.Contains(err.Error(), tc.wantIn) {
241					t.Fatalf("error = %q, want substring %q", err.Error(), tc.wantIn)
242				}
243			})
244		}
245	}
246	
247	// slide == window is exactly the fixed-window behavior.
248	func TestAggregateSlidingEqualsWindowMatchesFixed(t *testing.T) {
249		input := strings.Join([]string{
250			`{"type":"event","key":"b","time":800,"value":-2}`,
251			`{"type":"event","key":"a","time":1200,"value":5}`,
252			`{"type":"event","key":"a","time":1500,"value":7}`,
253			`{"type":"watermark","time":2000}`,
254		}, "\n")
255		slidingOut, _, err := runSliding(t, input, 1000, 1000)
256		if err != nil {
257			t.Fatalf("unexpected error: %v", err)
258		}
259		var fixed bytes.Buffer
260		if err := RunAggregate(strings.NewReader(input), 1000, &fixed, &bytes.Buffer{}); err != nil {
261			t.Fatalf("unexpected error: %v", err)
262		}
263		if slidingOut != fixed.String() {
264			t.Fatalf("slide==window output %q != fixed output %q", slidingOut, fixed.String())
265		}
266	}
267	
268	// A window end leaving the signed 64-bit range stops processing and reports
269	// the input line and offending window; prior output remains and later lines
270	// are not read.
271	func TestAggregateSlidingWindowEndOverflow(t *testing.T) {
272		input := strings.Join([]string{
273			`{"type":"event","key":"k","time":0,"value":1}`,
274			`{"type":"watermark","time":1000}`,
275			`{"type":"event","key":"k","time":9223372036854775807,"value":1}`,
276			`{"type":"event","key":"k","time":1,"value":1}`,
277		}, "\n")
278		// window=1000, slide=600: containing windows for MaxInt64 start near
279		// MaxInt64 and their ends overflow.
280		stdout, _, err := runSliding(t, input, 1000, 600)
281		if err == nil {
282			t.Fatal("expected overflow error")
283		}
284		inputErr, ok := err.(*InputError)
285		if !ok {
286			t.Fatalf("expected *InputError, got %T: %v", err, err)
287		}
288		if inputErr.Line != 3 {
289			t.Errorf("line = %d, want 3", inputErr.Line)
290		}
291		if !strings.Contains(inputErr.Reason, "window end overflow") {
292			t.Fatalf("reason = %q, want window end overflow", inputErr.Reason)
293		}
294		if !strings.Contains(inputErr.Reason, "window starting at") {
295			t.Fatalf("reason = %q, want it to name the offending window start", inputErr.Reason)
296		}
297		if got := stdout; got != `{"key":"k","start":0,"end":1000,"count":1,"sum":1}`+"\n" {
298			t.Fatalf("earlier output must be retained, got %q", got)
299		}
300	}
301	
302	// A cumulative sum overflow reached through overlapping windows is fatal for
303	// that input line and names the offending window.
304	func TestAggregateSlidingSumOverflow(t *testing.T) {
305		input := strings.Join([]string{
306			`{"type":"event","key":"k","time":700,"value":9223372036854775807}`,
307			`{"type":"event","key":"k","time":800,"value":1}`, // adds to both windows covering 700..800
308		}, "\n")
309		_, _, err := runSliding(t, input, 1000, 600)
310		if err == nil {
311			t.Fatal("expected cumulative sum overflow")
312		}
313		inputErr, ok := err.(*InputError)
314		if !ok {
315			t.Fatalf("expected *InputError, got %T: %v", err, err)
316		}
317		if inputErr.Line != 2 {
318			t.Errorf("line = %d, want 2", inputErr.Line)
319		}
320		if !strings.Contains(inputErr.Reason, "sum overflow") {
321			t.Fatalf("reason = %q, want sum overflow", inputErr.Reason)
322		}
323		if !strings.Contains(inputErr.Reason, "[0,1000)") {
324			t.Fatalf("overflow should name the offending window [0,1000), got %q", inputErr.Reason)
325		}
326	}
327	
328	// Overflow in a later containing window must not leave earlier windows of the
329	// same line partially updated: the failing event counts in no window.
330	func TestAggregateSlidingOverflowLeavesNoPartialUpdate(t *testing.T) {
331		// First event lands in [0,1000) and [600,1600); second positive overflow
332		// event is rejected, so a later watermark still shows count 1.
333		input := strings.Join([]string{
334			`{"type":"event","key":"k","time":700,"value":1}`,
335			`{"type":"event","key":"k","time":800,"value":9223372036854775807}`,
336			`{"type":"watermark","time":1600}`,
337		}, "\n")
338		stdout, _, err := runSliding(t, input, 1000, 600)
339		if err == nil {
340			t.Fatal("expected overflow error")
341		}
342		// Nothing closes before the fatal line, so no window should carry the
343		// rejected event; output is empty because the only watermark runs after
344		// the failure and is never reached.
345		if stdout != "" {
346			t.Fatalf("failing line must not update any window, got %q", stdout)
347		}
348	}
